cd out 2>/dev/null || mkdir -p out && cd out; cd ..; python3 - <<'E'
s=open('in/previous/transform.ts').read()
s=s.replace('''      condition: latest.e.DX_TEXT ?? code,''','''      condition: conditionText(latest),''')
s=s.replace('''function problems(entries''','''// Generic "Personal history of ..." codes carry no specific condition; the narrative span names it.
function conditionText(en: Entry): string {
  const text: string = en.e.DX_TEXT ?? en.e.ICD10CM;
  if (!/^personal history of/i.test(text)) return text;
  const m = new RegExp('<ref id="' + en.id.replace(/[^\\w-]/g, "") + '">([\\\\s\\\\S]*?)</ref>').exec(en.item.narrative ?? "");
  if (!m) return text;
  let t = m[1].replace(/\\s+/g, " ").trim();
  t = t.replace(/^(earlier|prior|previous|past|history of|hx of)\\s+/i, "")
    .replace(/\\s+(history|reviewed|remains.*)$/i, "")
    .replace(/\\s+(on|after|while on|from)\\s+.*$/i, "")
    .replace(/\\bDKA\\b/gi, "diabetic ketoacidosis").trim();
  if (t.length < 3 || t.length > 80) return text;
  return t.charAt(0).toUpperCase() + t.slice(1);
}

function problems(entries''',1)
open('out/transform.ts','w').write(s)
E
sh in/harness/check.sh 2>&1 | tail -30; grep -n "conditionText" -A6 out/transform.ts | head -12

